package com.rodentcontrol.customer;
import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import java.util.concurrent.Executors;
public class ReportsActivity extends AppCompatActivity{protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_detail);TextView v=findViewById(R.id.detail);Executors.newSingleThreadExecutor().execute(()->{try{org.json.JSONArray a=Api.reports(this).getJSONArray("reports");StringBuilder s=new StringBuilder("Báo cáo đã duyệt\n\n");for(int i=0;i<a.length();i++){org.json.JSONObject r=a.getJSONObject(i);s.append(r.optString("report_code", "BC-" + r.optInt("id"))).append(" | ").append(r.optString("site_name","Toàn bộ địa điểm")).append(" | ").append(r.optString("period_start")).append(" → ").append(r.optString("period_end")).append("\n");}runOnUiThread(()->v.setText(s.toString()));}catch(Exception e){runOnUiThread(()->v.setText(e.getMessage()));}});}}
